<template><div class="admin-applications-page"><AdminApplicationsTabs active="reviewers"/><DemoIdentitySwitcher/><div v-if="identity.role!=='admin'" class="applications-queue applications-state"><strong>Admin demo view required</strong></div><div v-else-if="!reviewer" class="applications-queue applications-state"><strong>Reviewer not found</strong></div><template v-else><header class="applications-page-header"><div><RouterLink class="application-back-link" :to="{name:'AdminReviewerPerformance'}">← Reviewer performance</RouterLink><h1>{{reviewer.reviewerName}}</h1><p>{{reviewer.reviewerStatus}} · fictional reviewer calibration profile</p></div><span class="calibration-badge">{{reviewer.calibrationStatus}}</span></header><section class="application-summary-grid"><article><strong>{{reviewer.sampleSize}}</strong><span>Completed reviews</span></article><article><strong>{{pct(reviewer.average)}}</strong><span>Average score</span></article><article><strong>{{pct(reviewer.median)}}</strong><span>Median score</span></article><article><strong>{{difference(reviewer.averagePeerDifference)}}</strong><span>Average peer difference</span></article><article><strong>{{pct(reviewer.commentCoverage)}}</strong><span>Comment coverage</span></article></section><div class="application-detail-grid"><main class="application-detail-main"><section class="application-panel"><h2>Score distribution</h2><div v-for="band in reviewer.distribution" :key="band.label" class="distribution-row"><span>{{band.label}}</span><div><i :style="{width:`${band.percentage}%`}"></i></div><strong>{{band.count}} · {{band.percentage}}%</strong></div></section><section class="application-panel"><h2>Review history</h2><div class="applications-table-scroll"><table class="applications-table"><thead><tr><th>Application</th><th>Date</th><th>Score</th><th>Peer mean</th><th>Difference</th><th>Provenance</th><th>Flags</th><th>Action</th></tr></thead><tbody><tr v-for="h in reviewer.history" :key="h.id"><td>{{h.applicationReference}}<small>{{h.pathwayLabel}}</small></td><td>{{date(h.submittedAt)}}</td><td>{{pct(h.percentage)}}</td><td>{{pct(h.peerMean)}}</td><td>{{difference(h.difference)}}</td><td>{{h.reviewLabel}}</td><td>{{h.seriousConcern?'Concern':h.clarification?'Clarification':'None'}}</td><td><RouterLink :to="{name:'AdminApplicationDetail',params:{applicationId:h.applicationId}}">View application</RouterLink></td></tr></tbody></table></div></section></main><aside class="application-panel"><h2>Consistency and completion</h2><dl class="metadata-list"><div><dt>Average absolute peer difference</dt><dd>{{reviewer.averageAbsoluteDifference}} pp</dd></div><div><dt>Largest peer difference</dt><dd>{{reviewer.largestDifference}} pp</dd></div><div><dt>Closely aligned</dt><dd>{{reviewer.closelyAligned}}</dd></div><div><dt>Material disagreement</dt><dd>{{reviewer.materialDisagreement}}</dd></div><div><dt>Average completion</dt><dd>{{reviewer.averageCompletionHours}} hours</dd></div><div><dt>Claims released</dt><dd>{{reviewer.released}}</dd></div><div><dt>Concern rate</dt><dd>{{pct(reviewer.concernRate)}}</dd></div><div><dt>Clarification rate</dt><dd>{{pct(reviewer.clarificationRate)}}</dd></div></dl><p class="panel-note">These are coaching and calibration indicators only. No single signal establishes unfairness or misconduct.</p></aside></div></template></div></template>
<script>import AdminApplicationsTabs from'./components/AdminApplicationsTabs.vue';import DemoIdentitySwitcher from'./components/DemoIdentitySwitcher.vue';import{demoWorkflow,getDemoIdentity}from'./applicationAdminData.js';import{getReviewerPerformance}from'./reviewerPerformanceData.js';export default{name:'AdminReviewerDetail',components:{AdminApplicationsTabs,DemoIdentitySwitcher},props:{reviewerId:{type:String,required:true}},data:()=>({workflow:demoWorkflow}),computed:{identity(){this.workflow.revision;return getDemoIdentity()},reviewer(){return this.identity.role==='admin'?getReviewerPerformance(this.reviewerId):null}},methods:{pct(v){return v===null?'—':`${v}%`},difference(v){if(v===null)return'Limited evidence';return`${v>0?'+':''}${v} pp`},date(v){return new Intl.DateTimeFormat('en-GB',{dateStyle:'medium'}).format(new Date(v))}}};</script><style src="./AdminApplications.css"></style>
